package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderFile *os.File
var reader *bufio.Reader
var orderRec OrderRec
var eofSeen bool

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func formatEdited(v decimal.Decimal, picture string) string {
	// split picture at '.'
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	// count digits
	intDigitCount := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigitCount++
		}
	}
	fracDigitCount := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			fracDigitCount++
		}
	}

	// integer part with overflow truncation
	// work with absolute value (all non-negative here)
	av := v
	if av.IsNegative() {
		av = av.Neg()
	}
	// truncate toward zero to get integer part
	intPartDec := av.Truncate(0)
	intPart := intPartDec.IntPart() // fits in int64 for this program
	var modVal int64
	if intDigitCount > 0 {
		p10 := pow10(intDigitCount)
		modVal = intPart % p10
		if modVal < 0 {
			modVal = -modVal
		}
	}
	// build digit array most significant first
	digits := make([]int, intDigitCount)
	tmp := modVal
	for i := intDigitCount - 1; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}

	// build integer part string
	var intOut strings.Builder
	digitIdx := 0
	suppress := true
	for _, ch := range intPic {
		if ch == ',' {
			if suppress {
				intOut.WriteByte(' ')
			} else {
				intOut.WriteByte(',')
			}
		} else if ch == 'Z' || ch == '9' {
			d := digits[digitIdx]
			if suppress {
				if d != 0 {
					suppress = false
					intOut.WriteByte(byte('0' + d))
				} else {
					if ch == '9' {
						suppress = false
						intOut.WriteByte('0')
					} else {
						intOut.WriteByte(' ')
					}
				}
			} else {
				intOut.WriteByte(byte('0' + d))
			}
			digitIdx++
		} else {
			intOut.WriteByte(byte(ch))
		}
	}

	if dotIdx < 0 {
		return intOut.String()
	}

	// fractional part
	// compute fractional digits
	var fracVal int64 = 0
	if fracDigitCount > 0 {
		p10f := pow10(fracDigitCount)
		// scale value
		scaled := av.Mul(decimal.NewFromInt(p10f)).Truncate(0).IntPart()
		// frac = scaled mod p10f (positive)
		fracVal = scaled % p10f
		if fracVal < 0 {
			fracVal = -fracVal
		}
	}
	// build frac digits array
	fracDigits := make([]int, fracDigitCount)
	tmp2 := fracVal
	for i := fracDigitCount - 1; i >= 0; i-- {
		fracDigits[i] = int(tmp2 % 10)
		tmp2 /= 10
	}
	var fracOut strings.Builder
	fIdx := 0
	for _, ch := range fracPic {
		if ch == '9' || ch == 'Z' {
			fracOut.WriteByte(byte('0' + fracDigits[fIdx]))
			fIdx++
		} else {
			fracOut.WriteByte(byte(ch))
		}
	}

	return intOut.String() + "." + fracOut.String()
}

func formatPIC99(v int64) string {
	// PIC 99 zero padded to 2
	// high-order truncation: keep low 2 digits
	if v < 0 {
		v = -v
	}
	v = v % 100
	return fmt.Sprintf("%02d", v)
}

func readOrderLine() (string, bool) {
	line, err := reader.ReadString('\n')
	if err != nil {
		// if we got some data before EOF, return it
		if len(line) > 0 {
			// strip trailing \r and \n
			line = strings.TrimRight(line, "\r\n")
			return line, true
		}
		return "", false
	}
	line = strings.TrimRight(line, "\r\n")
	return line, true
}

func parseOrderRec(raw string) OrderRec {
	// pad with spaces to 15
	if len(raw) < 15 {
		raw = raw + strings.Repeat(" ", 15-len(raw))
	} else if len(raw) > 15 {
		raw = raw[:15]
	}
	var rec OrderRec
	rec.OrId = raw[0:5]
	rec.OrStat = raw[5:6]
	qtyStr := raw[6:9]
	// parse qty digits
	var q int64 = 0
	for _, c := range qtyStr {
		if c >= '0' && c <= '9' {
			q = q*10 + int64(c-'0')
		} else {
			// COBOL numeric field with spaces? treat as 0? But input should be digits.
			// If non-digit, treat as 0 for that char? We'll just ignore.
			q = q * 10
		}
	}
	rec.OrQty = q

	priceStr := raw[9:15]
	var pDigits int64 = 0
	for _, c := range priceStr {
		if c >= '0' && c <= '9' {
			pDigits = pDigits*10 + int64(c-'0')
		} else {
			pDigits = pDigits * 10
		}
	}
	rec.OrPrice = decimal.New(pDigits, -2)
	return rec
}

func MAINPARA() {
	var err error
	orderFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	// defer close will be done after loop, but also need explicit close before summary
	reader = bufio.NewReader(orderFile)
	READPARA()
	for !INPUTDONE() {
		PROCESSPARA()
	}
	orderFile.Close()
	SUMMARYPARA()
}

func INPUTDONE() bool {
	return WsEofFlag == "Y"
}

func READPARA() {
	if eofSeen {
		return
	}
	line, ok := readOrderLine()
	if !ok {
		WsEofFlag = "Y"
		eofSeen = true
		return
	}
	orderRec = parseOrderRec(line)
}

func PROCESSPARA() {
	WsTotal = decimal.NewFromInt(0)
	// EVALUATE TRUE
	if orderRec.OrQty == 0 {
		WsBadQty++
		// DISPLAY OR-ID " BAD QTY"
		fmt.Printf("%s BAD QTY\n", orderRec.OrId)
	} else if orderRec.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE
		qtyDec := decimal.NewFromInt(orderRec.OrQty)
		prod := qtyDec.Mul(orderRec.OrPrice)
		// truncate to scale 2
		WsTotal = prod.Truncate(2)
		// high-order truncation to PIC 9(8)V99 if needed
		// keep low order digits: we can simulate by mod 10^(10)?? need to keep 8 integer digits +2 decimal
		// The value fits, but implement generic truncation
		// For PIC 9(8)V99, the stored integer = value *100 as integer, keep low 10 digits
		// We'll apply if overflow: but not needed for correctness of given tests maybe
		// Implement:
		WsTotal = truncateToPic(WsTotal, 8, 2)
		WsNewCount++
		SHOWPARA()
	} else if orderRec.OrStat == "S" {
		qtyDec := decimal.NewFromInt(orderRec.OrQty)
		prod := qtyDec.Mul(orderRec.OrPrice).Mul(decimal.NewFromFloat(1.05))
		// Actually use string to avoid binary float
		// Use decimal.NewFromString("1.05")
		// redo with exact
		prod = qtyDec.Mul(orderRec.OrPrice).Mul(decimal.RequireFromString("1.05"))
		WsTotal = prod.Round(2)
		WsTotal = truncateToPic(WsTotal, 8, 2)
		WsShipCount++
		SHOWPARA()
	} else if orderRec.OrStat == "C" {
		WsCancelCount++
		SHOWPARA()
	} else {
		WsInvalid++
		fmt.Printf("%s BAD STATUS %s\n", orderRec.OrId, orderRec.OrStat)
	}
	// ADD WS-TOTAL TO WS-GRAND
	WsGrand = WsGrand.Add(WsTotal)
	WsGrand = truncateToPic(WsGrand, 10, 2)
	READPARA()
}

func truncateToPic(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Keep low-order digits: v *10^scale as integer mod 10^(intDigits+scale)
	// Need to handle sign? assume positive
	totalDigits := intDigits + int(scale)
	p10 := pow10(totalDigits) // totalDigits up to 12, fits int64 (10^12=1e12)
	// scale v
	scaled := v.Mul(decimal.NewFromInt(pow10(int(scale)))).Truncate(0)
	// scaled may be large, get IntPart
	iv := scaled.IntPart()
	// high order truncation: keep low totalDigits digits with sign preservation?
	// COBOL keeps low-order digits, sign separate. For positive, modulo.
	// Need to handle negative correctly: truncate magnitude
	if iv < 0 {
		mod := iv % p10
		// Go mod negative yields negative remainder, we want keep magnitude low digits then reapply sign
		// So take absolute, mod, then negative
		abs := -iv
		absMod := abs % p10
		iv = -absMod
	} else {
		iv = iv % p10
	}
	return decimal.New(iv, -scale)
}

func SHOWPARA() {
	WsQtyEd = formatEdited(decimal.NewFromInt(orderRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(orderRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", orderRec.OrId, orderRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SUMMARYPARA() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", formatPIC99(WsNewCount), formatPIC99(WsShipCount), formatPIC99(WsCancelCount))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", formatPIC99(WsInvalid), formatPIC99(WsBadQty))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	MAINPARA()
}

